add_action( 'woocommerce_product_query', 'perfectpixel_hide_products_by_meta' );

function perfectpixel_hide_products_by_meta( $q ) {
	$key = sanitize_key( '{{hide_meta_key}}' );
	if ( '' === $key ) {
		return;
	}
	$meta_query   = (array) $q->get( 'meta_query' );
	$meta_query[] = array(
		'relation' => 'OR',
		array(
			'key'     => $key,
			'compare' => 'NOT EXISTS',
		),
		array(
			'key'     => $key,
			'value'   => '{{hide_meta_value}}',
			'compare' => '!=',
		),
	);
	$q->set( 'meta_query', $meta_query );
}
